```cpp
// 扫描特征码定位对象列表（示例）
DWORD64 FindPattern(HANDLE hProc, BYTE* pattern, const char* mask, SIZE_T size) {
    BYTE buf[0x10000]; MODULEINFO mi;
    GetModuleInformation(hProc, GetModuleHandleEx(...), &mi, sizeof(mi));
    for (SIZE_T i = 0; i < mi.SizeOfImage; i += sizeof(buf) - size) {
        ReadProcessMemory(hProc, (BYTE*)mi.lpBaseOfDll + i, buf, sizeof(buf), 0);
        for (SIZE_T j = 0; j < sizeof(buf) - size; j++) {
            for (SIZE_T k = 0; k < size; k++)
                if (mask[k] == 'x' && buf[j+k] != pattern[k]) goto next;
            return (DWORD64)mi.lpBaseOfDll + i + j;
            next:;
        }
    }
    return 0;
}
```

## 2. 内存读取（外部版）

```cpp
struct Vec3 { float x, y, z; };

DWORD64 GetModuleBase(DWORD pid, const char* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, pid);
    MODULEENTRY32 me{ sizeof(me) };
    Module32First(snap, &me);
    do { if (!_stricmp(me.szModule, mod)) { CloseHandle(snap); return (DWORD64)me.modBaseAddr; } }
    while (Module32Next(snap, &me));
    CloseHandle(snap); return 0;
}

Vec3 ReadVec3(HANDLE h, DWORD64 addr) {
    Vec3 v{}; ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(v), 0); return v;
}

void ReadEnemies(HANDLE h, DWORD pid) {
    DWORD64 base = GetModuleBase(pid, "LOCAL_GAME.exe");
    DWORD64 listAddr = 0;
    ReadProcessMemory(h, (LPCVOID)(base + 0xENTITY_LIST_OFFSET), &listAddr, 8, 0);
    int count = 0;
    ReadProcessMemory(h, (LPCVOID)(listAddr + 0xCOUNT_OFFSET), &count, 4, 0);

    for (int i = 0; i < count; i++) {
